import{_ as a,o as i,c as o,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Importar plantillas y administrar perfiles","description":"","frontmatter":{"title":"Importar plantillas y administrar perfiles","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","translationRevision":"e8c07fdcb5d0d3eb2b22d6577bbad8949d3af80d713151e95baf00bfe5df158c","order":50},"headers":[],"relativePath":"es/user/automations/templates.md","filePath":"es/user/automations/templates.md","lastUpdated":1794611623000}'),r={name:"es/user/automations/templates.md"};function t(l,e,n,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="import-templates-and-manage-profiles" tabindex="-1">Importar plantillas y administrar perfiles <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to &quot;Importar plantillas y administrar perfiles {#import-templates-and-manage-profiles}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Reutiliza una regla revisada o un conjunto de reglas sin activar efectos accidentalmente. Necesitas <strong>Automations</strong>, un archivo JSON o elemento de catálogo confiable y los plugins exigidos por sus acciones. Exporta el perfil actual antes de sustituir una configuración estable.</p><h2 id="choose-the-right-surface" tabindex="-1">Elegir la superficie adecuada <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;Elegir la superficie adecuada {#choose-the-right-surface}&quot;">​</a></h2><p>Un documento <code>.tiktemplate.json</code> describe un evento y sus acciones. Un <code>.tikprofile.json</code> agrupa varias plantillas. Abre el diálogo de plantillas desde Automations para consultar plantillas integradas o propias, su biblioteca Cloud o la importación manual. La barra de perfiles permite crear, seleccionar, exportar e importar perfiles manualmente. <strong>Plugins → Explore</strong> busca plugins; las plantillas y perfiles se administran aquí.</p><h2 id="review-and-import" tabindex="-1">Revisar e importar <a class="header-anchor" href="#review-and-import" aria-label="Permalink to &quot;Revisar e importar {#review-and-import}&quot;">​</a></h2><ol><li>Abre el diálogo correspondiente y elige un archivo o pega JSON compatible. Comprueba el nombre preparado y su origen antes de continuar.</li><li>Para una plantilla, inspecciona disparador, tipos de acción y parámetros. Para un perfil, revisa también el número de entradas y los parámetros comunes.</li><li>Sustituye destinos de ejemplo, rutas de medios e identificadores por valores adecuados a tu instalación. No pegues credenciales en archivos que vayas a compartir.</li><li>Aplica/importa explícitamente y espera el resultado. No supongas que las definiciones quedan desactivadas: revisa sus valores enabled. Selecciónalas después y revisa cada acción y evento antes de activar explícitamente los deseados.</li><li>Comienza con una prueba que solo registre texto o inspecciona primero las definiciones. Las pruebas de HTTP, audio, puntos y plugins pueden ejecutar efectos.</li><li>Antes de confirmar perfil, revisa que se habilitan miembros destino y deshabilitan los demás, incluidos registros sueltos y miembros antes desactivados. Los efectos requieren disparadores/condiciones; no es sync Cloud.</li></ol><p>Parámetros como <code>{{ params.giftName }}</code> se resuelven al aplicar la plantilla. Referencias como <code>{{ event.user.uniqueId }}</code> permanecen para cada evento; las <a href="./variables.html">variables globales</a> aportan valores compartidos durante la ejecución.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles las superficies locales de importación y exportación. La consulta de Cloud requiere capacidad del host, cuenta y servicio. Una vista previa del catálogo no demuestra que funcione el servicio externo de una acción. Si faltan plugins, las definiciones pueden quedar inutilizables hasta instalarlos y configurarlos.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si el JSON es inválido, sigue los errores del analizador y comprueba el tipo de documento: renombrar cualquier JSON no lo convierte. Ante conflictos de revisión, actualiza la biblioteca antes de repetir. Conserva el perfil exportado conocido y consulta <a href="./../preferences/backups.html">copias de seguridad</a> para los datos que la exportación no incluye.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Importar plantilla manual primero guarda un documento de catálogo; aplicarla crea acciones/eventos enlazados. El parser usa true si falta <code>enabled</code> y la aplicación conserva esos valores. Importar perfil manual también prepara sus entradas para revisión del propietario. El catálogo Cloud guarda plantillas; un perfil Cloud prepara mutación con procedencia. Ni el origen ni una vista previa correcta garantizan desactivación universal. Revisa comparación final y estados guardados. En CLI usa expresamente <code>tiktools template import file.tiktemplate.json --disabled</code> o <code>tiktools template profile-import file.tikprofile.json --disabled</code>.</p><p>Cambiar perfil modifica activación: confirmar habilita miembros destino y deshabilita todas las acciones/eventos ajenos, incluidos registros sueltos. Miembros destino previamente desactivados pueden activarse. Revisa ambas listas antes de confirmar. Los efectos requieren disparadores, condiciones y runtime; el cambio no envía sincronización Cloud por sí mismo.</p>',15)])])}const f=a(r,[["render",t]]);export{m as __pageData,f as default};
